B.a71=new A.bN(B.a7V,['(\u041c\u04b1\u0445\u0430\u043c\u043c\u0435\u0434 \u0492.\u0421.): "\u04d8\u0439 \u04e9\u0437\u0434\u0435\u0440\u0456\u043d\u0435 \u0437\u0438\u044f\u043d \u049b\u044b\u043b\u0493\u0430\u043d \u049b\u04b1\u043b\u0434\u0430\u0440\u044b\u043c! \u0410\u043b\u043b\u0430\u043d\u044b\u04a3 \u0440\u0430\u0445\u043c\u0435\u0442\u0456\u043d\u0435\u043d \u043a\u04af\u0434\u0435\u0440 \u04af\u0437\u0431\u0435\u04a3\u0434\u0435\u0440. \u0410\u043b\u043b\u0430 \u0431\u0456\u0440\u0442\u04b1\u0442\u0430\u0441 \u043a\u04af\u043d\u04d9\u043b\u0430\u0440\u0434\u044b \u0436\u0430\u0440\u044b\u043b\u049b\u0430\u0439\u0434\u044b. \u04e8\u0439\u0442\u043a\u0435\u043d\u0456 \u041e\u043b \u0442\u044b\u043c \u0436\u0430\u0440\u044b\u043b\u049b\u0430\u0443\u0448\u044b, \u0442\u04e9\u0442\u0435\u043d\u0448\u0435 \u043c\u0435\u0439\u0456\u0440\u0456\u043c\u0434\u0456" \u0434\u0435.',"(\u041c\u04b1\u0445\u0430\u043c\u043c\u0435\u0434 \u0492.\u0421.) \u049b\u04b1\u043b\u0434\u0430\u0440\u044b\u043c\u0430 \u0445\u0430\u0431\u0430\u0440 \u0431\u0435\u0440. \u041a\u04af\u0434\u0456\u043a\u0441\u0456\u0437 \u041c\u0435\u043d \u0430\u0441\u0430 \u0436\u0430\u0440\u044b\u043b\u049b\u0430\u0443\u0448\u044b, \u0435\u0440\u0435\u043a\u0448\u0435 \u043c\u0435\u0439\u0456\u0440\u0456\u043c\u0434\u0456\u043c\u0456\u043d.","\u0411\u0456\u0440\u0435\u0443 \u0431\u0456\u0440 \u0436\u0430\u043c\u0430\u043d\u0434\u044b\u049b \u0456\u0441\u0442\u0435\u0441\u0435 \u043d\u0435\u043c\u0435\u0441\u0435 \u04e9\u0437\u0456\u043d\u0435 \u0437\u04b1\u043b\u044b\u043c\u0434\u044b\u049b \u049b\u044b\u043b\u0441\u0430 \u0434\u0430, \u0441\u043e\u043d\u0441\u043e\u04a3 \u0410\u043b\u043b\u0430\u0434\u0430\u043d \u0436\u0430\u0440\u044b\u043b\u049b\u0430\u043d\u0443 \u0442\u0456\u043b\u0435\u0441\u0435, \u0410\u043b\u043b\u0430\u043d\u044b \u0430\u0441\u0430 \u0436\u0430\u0440\u044b\u043b\u049b\u0430\u0443\u0448\u044b, \u0435\u0440\u0435\u043a\u0448\u0435 \u043c\u0435\u0439\u0456\u0440\u0456\u043c\u0434\u0456 \u0442\u0430\u0431\u0430\u0440 \u0435\u0434\u0456.","\u041e\u043b, \u049b\u04b1\u043b\u0434\u0430\u0440\u044b\u043d\u044b\u04a3 \u0442\u04d9\u0443\u0431\u0435\u0441\u0456\u043d \u049b\u0430\u0431\u044b\u043b \u0435\u0442\u0435\u0434\u0456 \u0434\u0435 \u043a\u04af\u043d\u04d9\u043b\u0430\u0440\u044b\u043d \u043a\u0435\u0448\u0456\u0440\u0435\u0434\u0456. \u04d8\u0440\u0456 \u043d\u0435 \u0456\u0441\u0442\u0435\u0433\u0435\u043d\u0434\u0435\u0440\u0456\u04a3\u0434\u0456 \u0431\u0456\u043b\u0435\u0434\u0456.",'(\u0421\u043e\u043d\u0434\u0430\u0439-\u0430\u049b \u043e\u043b\u0430\u0440\u0493\u0430): "\u0420\u0430\u0431\u0431\u044b\u043b\u0430\u0440\u044b\u04a3\u043d\u0430\u043d \u0436\u0430\u0440\u044b\u043b\u049b\u0430\u0443 \u0442\u0456\u043b\u0435\u04a3\u0434\u0435\u0440. \u04e8\u0439\u0442\u043a\u0435\u043d\u0456 \u041e\u043b, \u04e9\u0442\u0435 \u0436\u0430\u0440\u044b\u043b\u049b\u0430\u0443\u0448\u044b." \u0434\u0435\u0434\u0456\u043c.',"\u201c\u0420\u0430\u0431\u0431\u044b\u043b\u0430\u0440\u044b\u04a3\u043d\u0430\u043d \u0436\u0430\u0440\u044b\u043b\u049b\u0430\u0443 \u0442\u0456\u043b\u0435\u04a3\u0434\u0435\u0440. \u0421\u043e\u043d\u0441\u043e\u04a3 \u041e\u0493\u0430\u043d \u0442\u04d9\u0443\u0431\u0435 \u049b\u044b\u043b\u044b\u04a3\u0434\u0430\u0440. \u0428\u044b\u043d\u044b\u043d\u0434\u0430 \u043c\u0435\u043d\u0456\u04a3 \u0420\u0430\u0431\u0431\u044b\u043c \u0435\u0440\u0435\u043a\u0448\u0435 \u043c\u0435\u0439\u0456\u0440\u0456\u043c\u0434\u0456, \u04e9\u0442\u0435 \u0441\u04af\u0439\u0433\u0456\u0448....\u201d","\u0410\u043b \u043e\u043b\u0430\u0440 \u049b\u0430\u0448\u0430\u043d \u0430\u0440\u0441\u044b\u0437\u0434\u044b\u049b \u0456\u0441\u0442\u0435\u0441\u0435 \u043d\u0435 \u04e9\u0437\u0434\u0435\u0440\u0456\u043d\u0435 \u0437\u04b1\u043b\u044b\u043c\u0434\u044b\u049b \u049b\u044b\u043b\u0441\u0430, \u0410\u043b\u043b\u0430\u043d\u044b \u0435\u0441\u0442\u0435\u0440\u0456\u043d\u0435 \u0430\u043b\u044b\u043f, \u043a\u04af\u043d\u04d9\u043b\u0430\u0440\u044b\u043d\u044b\u04a3 \u0436\u0430\u0440\u044b\u043b\u049b\u0430\u0443\u044b\u043d \u0442\u0456\u043b\u0435\u0439\u0434\u0456. \u041a\u04af\u043d\u04d9\u043b\u0430\u0440\u0434\u044b \u0410\u043b\u043b\u0430\u0434\u0430\u043d \u0431\u0430\u0441\u049b\u0430 \u043a\u0456\u043c \u0436\u0430\u0440\u044b\u043b\u049b\u0430\u0439\u0434\u044b. \u0421\u043e\u043d\u0434\u0430\u0439-\u0430\u049b \u043e\u043b\u0430\u0440 \u0456\u0441\u0442\u0435\u0433\u0435\u043d \u0456\u0441\u0442\u0435\u0440\u0456\u043d\u0435 \u0431\u0456\u043b\u0435 \u0442\u04b1\u0440\u0430 \u049b\u0430\u0441\u0430\u0440\u044b\u0441\u043f\u0430\u0439\u0434\u044b.","\u041e\u043b,\u0442\u044b\u043c \u0436\u0430\u0440\u044b\u043b\u049b\u0430\u0443\u0448\u044b,\u04e9\u0442\u0435 \u0441\u04af\u044e\u0448\u0456.","(\u041c\u04b1\u0445\u0430\u043c\u043c\u0435\u0434 \u0492.\u0421.) \u0411\u0456\u0437 \u0441\u0435\u043d\u0456 \u0431\u04af\u043a\u0456\u043b \u04d9\u043b\u0435\u043c\u0433\u0435 \u0440\u0430\u0445\u043c\u0435\u0442 \u0435\u0442\u0456\u043f \u049b\u0430\u043d\u0430 \u0436\u0456\u0431\u0435\u0440\u0434\u0456\u043a.","\u0415\u043d\u0434\u0456 \u0420\u0430\u0431\u0431\u044b\u04a3\u0434\u044b \u043c\u0430\u049b\u0442\u0430\u0439 \u0434\u04d9\u0440\u0456\u043f\u0442\u0435\u043f,\u041e\u0434\u0430\u043d \u0436\u0430\u0440\u044b\u043b\u049b\u0430\u0443 \u0442\u0456\u043b\u0435.\u041d\u0435\u0433\u0456\u0437\u0456\u043d\u0435\u043d \u0410\u043b\u043b\u0430,\u0442\u04d9\u0443\u0431\u0435\u043d\u0456 \u04e9\u0442\u0435 \u049b\u0430\u0431\u044b\u043b \u0435\u0442\u0443\u0448\u0456.","(\u041c\u04b1\u0445\u0430\u043c\u043c\u0435\u0434 \u0492.\u0421.) \u043e\u043b\u0430\u0440\u0493\u0430: \xab\u0415\u0433\u0435\u0440 \u0410\u043b\u043b\u0430\u043d\u044b \u0441\u04af\u0439\u0441\u0435\u043d\u0434\u0435\u0440, \u043e\u043d\u0434\u0430 \u043c\u0430\u0493\u0430\u043d \u0456\u043b\u0435\u0441\u0456\u04a3\u0434\u0435\u0440. \u0410\u043b\u043b\u0430 (\u0422.) \u0441\u0435\u043d\u0434\u0435\u0440\u0434\u0456 \u0436\u0430\u049b\u0441\u044b \u043a\u04e9\u0440\u0456\u043f, \u043a\u04af\u043d\u04d9\u043b\u0430\u0440\u044b\u04a3\u0434\u044b \u0436\u0430\u0440\u044b\u043b\u049b\u0430\u0439\u0434\u044b. \u04e8\u0439\u0442\u043a\u0435\u043d\u0456, \u0410\u043b\u043b\u0430 \u0430\u0441\u0430 \u0436\u0430\u0440\u044b\u043b\u049b\u0430\u0443\u0448\u044b, \u0435\u0440\u0435\u043a\u0448\u0435 \u043c\u0435\u0439\u0456\u0440\u0456\u043c\u0434\u0456\xbb \u0434\u0435.","\u0420\u0430\u0431\u0431\u044b\u04a3 \u0441\u0435\u043d\u0456 \u0442\u0430\u0441\u0442\u0430\u043c\u0430\u0434\u044b \u0434\u0430 \u043a\u0435\u0439\u0456\u043c\u0435\u0434\u0456.","(\u041c\u04b1\u0445\u0430\u043c\u043c\u0435\u0434 \u0492.\u0421.) \u0435\u0433\u0435\u0440 \u049b\u04b1\u043b\u0434\u0430\u0440\u044b\u043c, \u041c\u0435\u043d \u0442\u0443\u0440\u0430\u043b\u044b \u0441\u0435\u043d\u0435\u043d \u0441\u04b1\u0440\u0430\u0441\u0430: \xab\u04e8\u0442\u0435 \u0436\u0430\u049b\u044b\u043d\u043c\u044b\u043d, \u049b\u0430\u0448\u0430\u043d \u041c\u0435\u043d\u0435\u043d \u0442\u0456\u043b\u0435\u0441\u0435, \u0442\u0456\u043b\u0435\u0443\u0448\u0456\u043d\u0456\u04a3 \u0442\u0456\u043b\u0435\u0433\u0456\u043d \u049b\u0430\u0431\u044b\u043b \u0435\u0442\u0435\u043c\u0456\u043d. \u0415\u043d\u0434\u0435\u0448\u0435 \u043e\u043b\u0430\u0440 \u0434\u0430 \u04d9\u043c\u0456\u0440\u0456\u043c\u0434\u0456 \u049b\u0430\u0431\u044b\u043b \u0435\u0442\u0441\u0456\u043d. \u0416\u04d9\u043d\u0435 \u041c\u0430\u0493\u0430\u043d \u0441\u0435\u043d\u0441\u0456\u043d. \u04d8\u0440\u0438\u043d\u0435 \u0442\u0443\u0440\u0430 \u0436\u043e\u043b \u0442\u0430\u043f\u049b\u0430\u043d \u0431\u043e\u043b\u0430\u0440 \u0435\u0434\u0456\xbb","\u0415\u043d\u0434\u0456, \u041c\u0435\u043d\u0456 \u0435\u0441\u043a\u0435 \u0430\u043b\u044b\u04a3\u0434\u0430\u0440, \u041c\u0435\u043d \u0434\u0435 \u0441\u0435\u043d\u0434\u0435\u0440\u0434\u0456 \u0435\u0441\u043a\u0435 \u0430\u043b\u0430\u043c\u044b\u043d \u0436\u04d9\u043d\u0435 \u041c\u0430\u0493\u0430\u043d \u0448\u04af\u043a\u0456\u0440\u043b\u0456\u043a \u043a\u044b\u043b\u044b\u04a3\u0434\u0430\u0440 \u0434\u0430 \u049b\u0430\u0440\u0441\u044b \u0431\u043e\u043b\u043c\u0430\u04a3\u0434\u0430\u0440.","\u04d8\u0439 \u043c\u04af\u043c\u0456\u043d\u0434\u0435\u0440! \u0421\u0430\u0431\u044b\u0440 \u0436\u04d9\u043d\u0435 \u043d\u0430\u043c\u0430\u0437\u0431\u0435\u043d\u0435\u043d (\u0410\u043b\u043b\u0430\u0434\u0430\u043d) \u0436\u04d9\u0440\u0434\u0435\u043c \u0442\u0456\u043b\u0435\u04a3\u0434\u0435\u0440, \u043a\u04af\u0434\u0456\u043a\u0441\u0456\u0437 \u0410\u043b\u043b\u0430 (\u0422.) \u0441\u0430\u0431\u044b\u0440 \u0435\u0442\u0443\u0448\u0456\u043b\u0435\u0440\u043c\u0435\u043d \u0431\u0456\u0440\u0433\u0435.","\u0421\u043e\u043d\u0434\u0430\u0439 \u0438\u043c\u0430\u043d \u043a\u0435\u043b\u0442\u0456\u0440\u0433\u0435\u043d\u0434\u0435\u0440; \u0410\u043b\u043b\u0430\u043d\u044b \u0435\u0441\u043a\u0435 \u0430\u043b\u0443 \u0430\u0440\u049b\u044b\u043b\u044b \u043a\u04e9\u04a3\u0456\u043b\u0434\u0435\u0440\u0456 \u0436\u0430\u0439 \u0442\u0430\u043f\u049b\u0430\u043d\u0434\u0430\u0440. \u0415\u0441\u0442\u0435\u0440\u0456\u04a3\u0434\u0435 \u0431\u043e\u043b\u0441\u044b\u043d; \u0410\u043b\u043b\u0430\u043d\u044b \u0435\u0441\u043a\u0435 \u0430\u043b\u0443\u043c\u0435\u043d \u0436\u04af\u0440\u0435\u043a\u0442\u0435\u0440 \u043e\u0440\u043d\u044b\u0493\u0430\u0434\u044b.","\u041d\u0435\u0433\u0456\u0437\u0456\u043d\u0434\u0435 \u0430\u0443\u044b\u0440\u043b\u044b\u049b\u043f\u0435\u043d \u0431\u0456\u0440\u0433\u0435 \u0431\u0456\u0440 \u0436\u0435\u04a3\u0456\u043b\u0434\u0456\u043a \u0431\u0430\u0440.","\u041e\u0493\u0430\u043d, \u0410\u043b\u043b\u0430, \u043e\u0439\u043b\u0430\u043c\u0430\u0493\u0430\u043d \u0436\u0435\u0440\u0434\u0435\u043d \u0440\u0438\u0437\u044b\u049b \u0431\u0435\u0440\u0435\u0434\u0456. \u0410\u043b \u043a\u0456\u043c \u0410\u043b\u043b\u0430\u0493\u0430 \u0442\u04d9\u0443\u0435\u043a\u0435\u043b \u049b\u044b\u043b\u0441\u0430, \u0441\u043e\u043d\u0434\u0430 \u041e\u043b, \u043e\u0493\u0430\u043d \u0436\u0435\u0442\u0456\u043f \u0430\u0441\u0430\u0434\u044b. \u0421\u04e9\u0437\u0441\u0456\u0437 \u0410\u043b\u043b\u0430 \u04e9\u0437 \u0431\u04b1\u0439\u0440\u044b\u0493\u044b\u043d \u0430\u0442\u049b\u0430\u0440\u0430\u0434\u044b. \u0420\u0430\u0441\u044b\u043d\u0434\u0430 \u0410\u043b\u043b\u0430, \u04d9\u0440 \u043d\u04d9\u0440\u0441\u0435\u0433\u0435 \u0431\u0456\u0440 \u04e9\u043b\u0448\u0435\u0443 \u049b\u043e\u0439\u0493\u0430\u043d.",'\u0420\u0430\u0431\u0431\u044b\u043b\u0430\u0440\u044b\u04a3: "\u041c\u0430\u0493\u0430\u043d \u0436\u0430\u043b\u0431\u0430\u0440\u044b\u04a3\u0434\u0430\u0440! \u0422\u0456\u043b\u0435\u043a\u0442\u0435\u0440\u0456\u04a3\u0434\u0456 \u049b\u0430\u0431\u044b\u043b\u0434\u0430\u0439\u043c\u044b\u043d. \u0420\u0430\u0441\u044b\u043d\u0434\u0430 \u041c\u0430\u0493\u0430\u043d \u049b\u04b1\u043b\u0448\u044b\u043b\u044b\u049b \u049b\u044b\u043b\u0443\u0434\u0430\u043d \u043f\u0430\u04a3\u0441\u044b\u0493\u0430\u043d\u0434\u0430\u0440, \u043e\u043b\u0430\u0440 \u049b\u043e\u0440 \u0431\u043e\u043b\u044b\u043f, \u0442\u043e\u0437\u0430\u049b\u049b\u0430 \u043a\u0456\u0440\u0435\u0434\u0456" \u0434\u0435\u0439\u0434\u0456.',"\u049a\u0430\u0448\u0430\u043d \u0441\u0430\u0493\u0430\u043d \u0430\u044f\u0442\u0442\u0430\u0440\u044b\u043c\u044b\u0437\u0493\u0430 \u0441\u0435\u043d\u0433\u0435\u043d\u0434\u0435\u0440 \u043a\u0435\u043b\u0441\u0435: \xab\u0421\u04d9\u043b\u0430\u043c\u04af\u043d \u0492\u0430\u043b\u0435\u0439\u043a\u04af\u043c (\u0421\u0435\u043d\u0434\u0435\u0440\u0433\u0435 \u0435\u0441\u0435\u043d\u0434\u0456\u043a \u0431\u043e\u043b\u0441\u044b\u043d)\xbb \u0434\u0435. \u0420\u0430\u0431\u0431\u044b\u043b\u0430\u0440\u044b\u04a3 \u043c\u04d9\u0440\u0445\u0430\u043c\u0435\u0442 \u0435\u0442\u0443\u0434\u0456 \u04e9\u0437 \u04af\u0441\u0442\u0456\u043d\u0435 \u0430\u043b\u0493\u0430\u043d. \u0428\u04d9\u043a\u0441\u0456\u0437 \u0410\u043b\u043b\u0430, \u0441\u0435\u043d\u0434\u0435\u0440\u0434\u0435\u043d \u0431\u0456\u0440\u0435\u0443, \u0431\u0456\u043b\u043c\u0435\u0439 \u0431\u0456\u0440 \u0436\u0430\u043c\u0430\u043d\u0434\u044b\u049b \u0456\u0441\u0442\u0435\u043f, \u0441\u043e\u043d\u0430\u043d \u043a\u0435\u0439\u0456\u043d \u0442\u04d9\u0443\u0431\u0435 \u049b\u044b\u043b\u044b\u043f, \u04e9\u0437\u0456\u043d \u0442\u04af\u0437\u0435\u043b\u0442\u0441\u0435, \u0441\u04e9\u0437 \u0436\u043e\u049b. \u0410\u043b\u043b\u0430 \u0430\u0441\u0430 \u0436\u0430\u0440\u044b\u043b\u049b\u0430\u0443\u0448\u044b, \u0435\u0440\u0435\u043a\u0448\u0435 \u043c\u0435\u0439\u0456\u0440\u0456\u043c\u0434\u0456. (54) \u041e\u0441\u044b\u043b\u0430\u0439\u0448\u0430 \u043a\u04af\u043d\u04d9\u043a\u0430\u0440\u043b\u0430\u0440\u0434\u044b\u04a3 \u0436\u043e\u043b\u044b \u0430\u043d\u044b\u049b\u0442\u0430\u043b\u0443\u044b \u04af\u0448\u0456\u043d \u0430\u044f\u0442\u0442\u0430\u0440\u044b\u043c\u044b\u0437\u0434\u044b \u0430\u0448\u0430\u043b\u0430\u043f \u0431\u0430\u044f\u043d \u0435\u0442\u0435\u043c\u0456\u0437.","\u041d\u0435\u0433\u0456\u0437\u0456\u043d\u0435\u043d \u0410\u043b\u043b\u0430 \u0441\u0435\u043d\u0434\u0435\u0440\u0433\u0435 \u0436\u0435\u04a3\u0456\u043b\u0434\u0456\u043a\u0442\u0456 \u049b\u0430\u043b\u0430\u0439\u0434\u044b. \u04e8\u0439\u0442\u043a\u0435\u043d\u0456 \u0430\u0434\u0430\u043c \u0431\u0430\u043b\u0430\u0441\u044b \u043d\u0430\u0448\u0430\u0440 \u0436\u0430\u0440\u0430\u0442\u044b\u043b\u0493\u0430\u043d.","\u0411\u0456\u0440\u0430\u049b \u043a\u0456\u043c\u0434\u0435-\u043a\u0456\u043c \u0442\u04d9\u0443\u0431\u0435 \u049b\u044b\u043b\u0441\u0430, \u0421\u043e\u043d\u0434\u0430\u0439-\u0430\u049b \u043a\u0456\u043c \u0438\u043c\u0430\u043d \u043a\u0435\u043b\u0442\u0456\u0440\u0456\u043f, \u0456\u0437\u0433\u0456 \u0456\u0441 \u0456\u0441\u0442\u0435\u0441\u0435, \u043c\u0456\u043d\u0435 \u0410\u043b\u043b\u0430 \u043e\u043b\u0430\u0440\u0434\u044b\u04a3 \u0436\u0430\u043c\u0430\u043d\u0434\u044b\u049b\u0442\u0430\u0440\u044b\u043d \u0436\u0430\u049b\u0441\u044b\u043b\u044b\u049b\u0442\u0430\u0440\u0493\u0430 \u0430\u0443\u044b\u0441\u0442\u044b\u0440\u0430\u0434\u044b. \u0410\u043b\u043b\u0430 \u04e9\u0442\u0435 \u0436\u0430\u0440\u044b\u043b\u049b\u0430\u0443\u0448\u044b, \u0435\u0440\u0435\u043a\u0448\u0435 \u043c\u0435\u0439\u0456\u0440\u0456\u043c\u0434\u0456.","\u04e8\u0439\u0442\u043a\u0435\u043d\u0456; \u041c\u0435\u043d, \u043a\u0456\u043c \u0442\u04d9\u0443\u0431\u0435 \u0435\u0442\u0456\u043f, \u0438\u043c\u0430\u043d \u043a\u0435\u043b\u0442\u0456\u0440\u0456\u043f, \u0438\u0433\u0456\u043b\u0456\u043a \u0456\u0441\u0442\u0435\u043f, \u0442\u0443\u0440\u0430 \u0436\u043e\u043b\u0434\u0430 \u0431\u043e\u043b\u0441\u0430; \u04d9\u043b\u0431\u0435\u0442\u0442\u0435 \u0436\u0430\u0440\u044b\u043b\u049b\u0430\u0439\u043c\u044b\u043d. (\u041c\u04b1\u0441\u0430 \u0492.\u0421. \u0435\u043b\u0456\u043d\u0435\u043d \u0441\u0430\u0439\u043b\u0430\u043f \u0430\u043b\u0493\u0430\u043d \u0436\u0435\u0442\u043f\u0456\u0441 \u043a\u0456\u0441\u0456\u043c\u0435\u043d \u0422\u04b1\u0440 \u0442\u0430\u0443\u044b\u043d\u0430 \u0436\u04af\u0440\u0433\u0435\u043d\u0434\u0435, \u043e\u043b\u0430\u0440\u0434\u0430\u043d \u043e\u0437\u0430 \u0436\u04af\u0440\u0433\u0435\u043d \u0435\u043a\u0435\u043d. 7-\u0421155-\u0410.)","\u201c\u04d8\u0439 \u04b1\u043b\u0434\u0430\u0440\u044b\u043c! \u0411\u0430\u0440\u044b\u04a3\u0434\u0430\u0440 \u0434\u0430 \u042e\u0441\u044b\u043f\u0442\u044b \u0436\u04d9\u043d\u0435 \u0442\u0443\u044b\u0441\u044b\u043d \u0456\u0437\u0434\u0435\u0441\u0442\u0456\u0440\u0456\u04a3\u0434\u0435\u0440! \u0421\u043e\u043d\u0434\u0430\u0439-\u0430\u049b \u0410\u043b\u043b\u0430\u043d\u044b\u04a3 \u043c\u04d9\u0440\u0445\u0430\u043c\u0435\u0442\u0456\u043d\u0435\u043d \u043a\u04af\u0434\u0435\u0440 \u04af\u0437\u0431\u0435\u04a3\u0434\u0435\u0440. \u04e8\u0439\u0442\u043a\u0435\u043d\u0456, \u0410\u043b\u043b\u0430\u043d\u044b\u04a3 \u0440\u0430\u0445\u043c\u0435\u0442\u0456\u043d\u0435\u043d, \u049b\u0430\u0440\u0441\u044b \u0431\u043e\u043b\u0493\u0430\u043d \u049b\u0430\u0443\u044b\u043c \u0493\u0430\u043d\u0430 \u043a\u04af\u0434\u0435\u0440 \u04af\u0437\u0435\u0434\u0456...\u201d","\u0421\u043e\u043b \u0443\u0430\u049b\u044b\u0442\u0442\u0430 \u0420\u0430\u0431\u0431\u044b\u043b\u0430\u0440\u044b\u04a3: \u201c\u0415\u0433\u0435\u0440 \u0448\u04af\u043a\u0456\u0440 \u0435\u0442\u0441\u0435\u04a3\u0434\u0435\u0440, \u0430\u0440\u0442\u0442\u044b\u0440\u0430 \u0431\u0435\u0440\u0435\u043c\u0456\u043d. \u0410\u043b, \u0435\u0433\u0435\u0440 \u049b\u0430\u0440\u0441\u044b \u043a\u0435\u043b\u0441\u0435\u04a3\u0434\u0435\u0440, \u0430\u0437\u0430\u0431\u044b\u043c \u0442\u044b\u043c \u049b\u0430\u0442\u0442\u044b\u201d \u0434\u0435\u043f \u0436\u0430\u0440\u0438\u044f\u043b\u0430\u0434\u044b.","\u0421\u043e\u043d\u0434\u0430\u0439 \u0436\u043e\u043b\u044b\u043c\u044b\u0437\u0434\u0430 \u043a\u04af\u0440\u0435\u0441\u043a\u0435\u043d\u0434\u0435\u0440\u0434\u0456 \u04d9\u043b\u0431\u0435\u0442\u0442\u0435 \u0442\u0443\u0440\u0430 \u0436\u043e\u043b\u0434\u0430\u0440\u044b\u043c\u044b\u0437\u0493\u0430 \u0441\u0430\u043b\u0430\u043c\u044b\u0437. \u0420\u0430\u0441 \u0410\u043b\u043b\u0430 \u0436\u0430\u049b\u0441\u044b\u043b\u044b\u049b \u0456\u0441\u0442\u0435\u0443\u043f\u0448\u0456\u043b\u0435\u0440\u043c\u0435\u043d \u0431\u0456\u0440\u0433\u0435.","(\u041c\u04b1\u0441\u044b\u043b\u043c\u0430\u043d\u0434\u0430\u0440!) \u0411\u043e\u0441\u0430\u043c\u0430\u04a3\u0434\u0430\u0440 \u0434\u0430 \u049b\u0430\u0439\u0493\u044b\u0440\u043c\u0430\u04a3\u0434\u0430\u0440. \u0415\u0433\u0435\u0440 \u043c\u04af\u043c\u0456\u043d \u0431\u043e\u043b\u0441\u0430\u04a3\u0434\u0430\u0440, \u04d9\u043b\u0431\u0435\u0442\u0442\u0435 \u04af\u0441\u0442\u0435\u043c \u0431\u043e\u043b\u0430\u0441\u044b\u04a3\u0434\u0430\u0440.","\u041e\u043b\u0430\u0440\u0493\u0430 \u0430\u0434\u0430\u043c\u0434\u0430\u0440: \xab\u0421\u0435\u043d\u0434\u0435\u0440 \u04af\u0448\u0456\u043d \u0435\u043b \u0436\u0438\u043d\u0430\u043b\u0434\u044b, \u0441\u043e\u043d\u0434\u044b\u049b\u0442\u0430\u043d \u043e\u043b\u0430\u0440\u0434\u0430\u043d \u049b\u043e\u0440\u049b\u044b\u04a3\u0434\u0430\u0440\xbb \u0434\u0435\u0434\u0456. (\u0411\u04b1\u043b \u0441\u04e9\u0437) \u043e\u043b\u0430\u0440\u0434\u044b\u04a3 \u0438\u043c\u0430\u043d\u044b\u043d \u0430\u0440\u0442\u0442\u044b\u0440\u0434\u044b \u0434\u0430 \u043e\u043b\u0430\u0440: \xab\u0411\u0456\u0437\u0433\u0435 \u0410\u043b\u043b\u0430 \u0436\u0435\u0442\u0456\u043f \u0430\u0441\u0430\u0434\u044b, \u041e\u043b \u043d\u0435\u043d\u0434\u0435\u0439 \u0436\u0430\u049b\u0441\u044b \u0438\u0435\xbb \u0434\u0435\u0434\u0456.","\u0421\u0430\u0431\u044b\u0440 \u0436\u04d9\u043d\u0435 \u043d\u0430\u043c\u0430\u0437\u0431\u0435\u043d \u0436\u04d9\u0440\u0434\u0435\u043c \u0442\u0456\u043b\u0435\u04a3\u0434\u0435\u0440. \u0420\u0430\u0441\u044b\u043d\u0434\u0430 \u043d\u0430\u043c\u0430\u0437 \u044b\u043d\u0442\u0430\u043b\u044b\u043b\u0430\u0440\u0434\u0430\u043d \u0431\u0430\u0441\u049b\u0430\u043b\u0430\u0440\u0493\u0430 \u0430\u0443\u044b\u0440 \u043a\u0435\u043b\u0435\u0434\u0456.",'(\u041c\u04b1\u0445\u0430\u043c\u043c\u0435\u0434 \u0492.\u0421.): "\u04d8\u0439 \u0438\u043c\u0430\u043d \u043a\u0435\u043b\u0442\u0456\u0440\u0433\u0435\u043d \u049b\u04b1\u043b\u0434\u0430\u0440\u044b\u043c! \u0420\u0430\u0431\u0431\u044b\u043b\u0430\u0440\u044b\u04a3\u043d\u0430\u043d \u049b\u043e\u0440\u049b\u044b\u04a3\u0434\u0430\u0440! \u0411\u04b1\u043b \u0434\u04af\u043d\u0438\u0435\u0434\u0435 \u0436\u0430\u049b\u0441\u044b\u043b\u044b\u049b \u0456\u0441\u0442\u0435\u0433\u0435\u043d\u0434\u0435\u0440\u0433\u0435 \u0436\u0430\u049b\u0441\u044b\u043b\u044b\u049b \u0431\u0430\u0440. \u0410\u043b\u043b\u0430\u043d\u044b\u04a3 \u0436\u0435\u0440\u0456 \u043a\u0435\u04a3. \u0428\u044b\u043d \u043c\u04d9\u043d\u0456\u043d\u0434\u0435 \u0441\u0430\u0431\u044b\u0440 \u0435\u0442\u0443\u0448\u0456\u043b\u0435\u0440\u0433\u0435 \u0441\u044b\u0439\u043b\u044b\u049b\u0442\u0430\u0440\u044b \u0435\u0441\u0435\u043f\u0441\u0456\u0437 \u043e\u0440\u044b\u043d\u0434\u0430\u043b\u0430\u0434\u044b" \u0434\u0435\u043f \u0430\u0439\u0442.',"\u0420\u0430\u0441\u044b\u043d\u0434\u0430 \u0430\u0434\u0430\u043c\u0437\u0430\u0442\u0442\u044b \u0436\u0430\u0440\u0430\u0442\u0442\u044b\u049b.\u041e\u0493\u0430\u043d, \u043d\u04d9\u043f\u0441\u0456\u0441\u0456\u043d\u0456\u04a3 \u043d\u0435 \u0441\u044b\u0431\u044b\u0440\u043b\u0430\u0493\u0430\u043d\u044b\u043d \u0431\u0456\u043b\u0435\u043c\u0456\u0437. \u04e8\u0439\u0442\u043a\u0435\u043d\u0456 \u0411\u0456\u0437, \u043e\u0493\u0430\u043d \u043a\u04af\u0440\u0435 \u0442\u0430\u043c\u044b\u0440\u044b\u043d\u0430\u043d \u0434\u0430 \u0436\u0430\u049b\u044b\u043d\u0431\u044b\u0437.","\u0415\u0440 \u043d\u0435\u043c\u0435\u0441\u0435 \u04d9\u0439\u0435\u043b\u0434\u0435\u043d \u043a\u0456\u043c \u0441\u0435\u043d\u0433\u0435\u043d \u0431\u043e\u0439\u0434\u0430 \u0442\u04af\u0437\u0443 \u0456\u0441 \u0456\u0441\u0442\u0435\u0441\u0435, \u04d9\u043b\u0431\u0435\u0442\u0442\u0435 \u043e\u043d\u044b \u0436\u0430\u049b\u0441\u044b \u0442\u0456\u0440\u0448\u0456\u043b\u0456\u043a\u0442\u0435 \u0436\u0430\u0441\u0430\u0442\u0430\u043c\u044b\u0437. \u04d8\u0440\u0456 \u043e\u043b\u0430\u0440\u0493\u0430 \u0456\u0441\u0442\u0435\u0433\u0435\u043d \u0456\u0441\u0442\u0435\u0440\u0456\u043d\u0435\u043d \u0436\u0430\u049b\u0441\u044b\u0440\u0430\u049b \u0441\u044b\u0439\u043b\u044b\u049b \u0431\u0435\u0440\u0435\u043c\u0456\u0437.","\u04d8\u0439 \u043c\u04af\u043c\u0456\u043d\u0434\u0435\u0440! \u0410\u043b\u043b\u0430\u043d\u044b \u04e9\u0442\u0435 \u043a\u04e9\u043f \u0437\u0456\u043a\u0456\u0440 \u0435\u0442\u0456\u04a3\u0434\u0435\u0440.","\u041e\u043b \u0435\u043a\u0435\u0443\u0456\u043d\u0435 \u043a\u0456\u0448\u0456\u0440\u0435\u0439\u0456\u043f \u043c\u04d9\u0440\u0445\u0430\u043c\u0435\u0442 \u049b\u04b1\u0448\u0430\u0493\u044b\u043d \u0436\u0430\u0439 \u0434\u0430: \u201c\u0420\u0430\u0431\u0431\u044b\u043c! \u041e\u043b \u0435\u043a\u0435\u0443\u0456 \u043c\u0435\u043d\u0456 \u043a\u0456\u0448\u043a\u0435\u043d\u0442\u0430\u0439\u0434\u0430 \u0442\u04d9\u0440\u0431\u0438\u0435\u043b\u0435\u0433\u0435\u043d\u0434\u0435\u0439 \u0421\u0435\u043d \u0434\u0435 \u043e\u043b\u0430\u0440\u0434\u044b \u043c\u04d9\u0440\u0445\u0430\u043c\u0435\u0442\u0456\u04a3\u0435 \u0431\u04e9\u043b\u0435\u0439 \u043a\u04e9\u0440!\u201d,-\u0434\u0435.","\u0428\u044b\u043d \u043c\u04d9\u043d\u0456\u043d\u0434\u0435 \u043c\u04af\u043c\u0456\u043d\u0434\u0435\u0440 \u0442\u0443\u044b\u0441 \u049b\u043e\u0439. \u0421\u043e\u043d\u0434\u044b\u049b\u0442\u0430\u043d \u0435\u043a\u0456 \u0442\u0443\u044b\u0441\u0442\u0430\u0440\u044b\u04a3\u043d\u044b\u04a3 \u0430\u0440\u0430\u0441\u044b\u043d \u0436\u0430\u0440\u0430\u0441\u0442\u044b\u0440\u044b\u04a3\u0434\u0430\u0440. \u0416\u04d9\u043d\u0435 \u0410\u043b\u043b\u0430\u0434\u0430\u043d \u049b\u043e\u0440\u049b\u044b\u04a3\u0434\u0430\u0440. \u041c\u04af\u043c\u043a\u0456\u043d \u0438\u0433\u0456\u043b\u0456\u043a\u043a\u0435 \u0431\u04e9\u043b\u0435\u043d\u0435\u0440\u0441\u0456\u04a3\u0434\u0435\u0440.","\u04d8\u0439 \u0430\u0434\u0430\u043c \u0431\u0430\u043b\u0430\u0441\u044b! \u0428\u04af\u0431\u04d9\u0441\u044b\u0437 \u0441\u0435\u043d\u0434\u0435\u0440\u0434\u0456 \u0431\u0456\u0440 \u0435\u0440, \u0431\u0456\u0440 \u04d9\u0439\u0435\u043b\u0434\u0435\u043d (\u0410\u0434\u0430\u043c, \u0425\u0430\u0443\u0430\u0434\u0430\u043d) \u0436\u0430\u0440\u0430\u0442\u0442\u044b\u049b. \u0421\u043e\u043d\u0434\u0430\u0439-\u0430\u049b \u0431\u0456\u0440-\u0431\u0456\u0440\u0456\u04a3\u0434\u0456 \u0442\u0430\u043d\u0443\u043b\u0430\u0440\u044b\u04a3 \u04af\u0448\u0456\u043d \u0441\u0435\u043d\u0434\u0435\u0440\u0434\u0456 \u04b1\u043b\u0442\u0442\u0430\u0440, \u0440\u0443\u043b\u0430\u0440 \u049b\u044b\u043b\u0434\u044b\u049b. \u0428\u044b\u043d\u044b\u043d\u0434\u0430 \u0410\u043b\u043b\u0430\u043d\u044b\u04a3 \u049b\u0430\u0441\u044b\u043d\u0434\u0430 \u0435\u04a3 \u0430\u0440\u0434\u0430\u049b\u0442\u044b\u043b\u0430\u0440\u044b\u04a3 \u0442\u0430\u049b\u0443\u0430\u043b\u0430\u0440\u044b\u04a3. \u0428\u04d9\u043a\u0441\u0456\u0437 \u0410\u043b\u043b\u0430 \u0442\u043e\u043b\u044b\u049b \u0431\u0456\u043b\u0443\u0448\u0456, \u04d9\u0440 \u043d\u04d9\u0440\u0441\u0435\u0434\u0435\u043d \u0445\u0430\u0431\u0430\u0440 \u0430\u043b\u0443\u0448\u044b.","(\u04d8\u0439 \u0410\u043b\u043b\u0430!) \u0421\u0430\u0493\u0430\u043d \u0493\u0430\u043d\u0430 \u049b\u04b1\u043b\u0448\u044b\u0434\u044b\u049b \u049b\u044b\u043b\u0430\u043c\u044b\u0437, \u04d9\u0440\u0456 \u0421\u0435\u043d\u0435\u043d \u0493\u0430\u043d\u0430 \u0436\u04d9\u0440\u0434\u0435\u043c \u0442\u0456\u043b\u0435\u0439\u043c\u0456\u0437!",u.Nr,"\u0416\u04d9\u043d\u0435 \u043e\u043b\u0430\u0440\u0434\u0430\u043d \u043a\u0456\u043c: \xab\u0420\u0430\u0431\u0431\u044b\u043c\u044b\u0437! \u0411\u0456\u0437\u0433\u0435 \u0434\u04af\u043d\u0438\u0435\u0434\u0435 \u0434\u0435 \u0436\u0430\u049b\u0441\u044b\u043b\u044b\u049b \u0431\u0435\u0440 \u04d9\u0440\u0456 \u0430\u0445\u0438\u0440\u0435\u0442\u0442\u0435 \u0434\u0435 \u0436\u0430\u049b\u0441\u044b\u043b\u044b\u049b \u0431\u0435\u0440. \u0416\u04d9\u043d\u0435 \u0442\u043e\u0437\u0430\u049b \u043e\u0442\u044b\u043d\u044b\u04a3 \u0430\u0437\u0430\u0431\u044b\u043d\u0430\u043d \u0441\u0430\u049b\u0442\u0430!\xbb,- \u0434\u0435\u0439\u0434\u0456.",'\u0428\u044b\u043d\u0430\u0439\u044b \u043c\u0435\u04a3\u0433\u0435\u0440\u0443\u0448\u0456 \u0410\u043b\u043b\u0430 \u04d9\u0440 \u043d\u04d9\u0440\u0441\u0435\u0434\u0435\u043d \u0436\u043e\u0493\u0430\u0440\u044b. (\u041c\u04b1\u0445\u0430\u043c\u043c\u0435\u0434 \u0492.\u0421.) \u0441\u0430\u0493\u0430\u043d \u0435\u0442\u0456\u043b\u0433\u0435\u043d \u0443\u0430\u0445\u0438 \u0431\u0456\u0442\u0443\u0434\u0435\u043d \u0431\u04b1\u0440\u044b\u043d \u049a\u04b1\u0440\u0430\u043d\u0434\u044b \u043e\u049b\u0443\u0493\u0430 \u0430\u0441\u044b\u049b\u043f\u0430 \u0434\u0430: "\u0420\u0430\u0431\u0431\u044b\u043c, \u0431\u0456\u043b\u0456\u043c\u0456\u043c\u0434\u0456 \u0430\u0440\u0442\u0442\u044b\u0440!",- \u0434\u0435.','\u0420\u0430\u0445\u043c\u0430\u043d\u044b\u04a3 \u049b\u04af\u043b\u0434\u0430\u0440\u044b \u0436\u0435\u0440\u0434\u0435 \u0441\u044b\u043f\u0430\u0439\u044b \u0442\u04af\u0440\u0434\u0435 \u0436\u04af\u0440\u0456\u043f, \u043e\u043b\u0430\u0440\u0493\u0430 \u0431\u0456\u043b\u043c\u0435\u0441\u0442\u0435\u0440 \u0442\u0456\u043b \u0442\u0438\u0433\u0456\u0437\u0441\u0435 \u0434\u0435: "\u0421\u04d9\u043b\u0435\u043c\u0435\u0442\u0448\u0456\u043b\u0456\u043a" \u0434\u0435\u043f, \u0434\u04b1\u0440\u044b\u0441 \u0436\u0430\u0443\u0430\u043f \u0431\u0435\u0440\u0435\u0434\u0456.',"\u0416\u0430\u049b\u0441\u044b\u043b\u044b\u049b \u043f\u0435\u043d \u0436\u0430\u043c\u0430\u043d\u0434\u044b\u049b \u0442\u0435\u04a3 \u0435\u043c\u0435\u0441. \u0416\u0430\u043c\u0430\u043d\u0434\u044b\u049b\u0442\u044b \u0435\u04a3 \u043a\u04e9\u0440\u043a\u0435\u043c \u0442\u04af\u0440\u0434\u0435 \u0436\u043e\u043b\u0493\u0430 \u0441\u0430\u043b. (\u0416\u0430\u043c\u0430\u043d\u0434\u044b\u049b\u049b\u0430 \u049b\u0430\u0440\u0441\u044b \u0436\u0430\u049b\u0441\u044b\u043b\u044b\u049b \u049b\u044b\u043b.) \u0421\u043e\u043b \u0443\u0430\u049b\u044b\u0442\u0442\u0430 \u0441\u0435\u043d\u0456 \u043c\u0435\u043d \u0435\u043a\u0435\u0443\u0456\u04a3 \u0430\u0440\u0430\u04a3\u0434\u0430 \u0434\u04b1\u0448\u043f\u0430\u043d\u0434\u044b\u049b \u0431\u043e\u043b\u0493\u0430\u043d \u0431\u0456\u0440\u0435\u0443, \u04e9\u0442\u0435 \u0436\u0430\u049b\u044b\u043d \u0434\u043e\u0441\u0442\u0430\u0439 \u0431\u043e\u043b\u044b\u043f \u043a\u0435\u0442\u0435\u0434\u0456.","(\u0410\u0434\u0430\u043c \u0430\u0442\u0430 \u043c\u0435\u043d \u0425\u0430\u0443\u0430 \u0430\u043d\u0430): \xab\u0420\u0430\u0431\u0431\u044b\u043c\u044b\u0437, \u0431\u0456\u0437 \u04e9\u0437\u0456\u043c\u0456\u0437\u0433\u0435 \u043a\u0435\u0441\u0456\u0440 \u0456\u0441\u0442\u0435\u0434\u0456\u043a. \u0415\u0433\u0435\u0440 \u0421\u0435\u043d \u0431\u0456\u0437\u0434\u0456 \u0436\u0430\u0440\u044b\u043b\u049b\u0430\u043f, \u043c\u04d9\u0440\u0445\u0430\u043c\u0435\u0442 \u0435\u0442\u043f\u0435\u0441\u0435\u04a3 \u04d9\u043b\u0431\u0435\u0442\u0442\u0435 \u0437\u0438\u044f\u043d \u0435\u0442\u0443\u0448\u0456\u043b\u0435\u0440\u0434\u0435\u043d \u0431\u043e\u043b\u0430\u043c\u044b\u0437\xbb \u0434\u0435\u0434\u0456.",'\u04d8\u0439\u04af\u043f (\u0492.\u0421.) \u0442\u0435 \u0420\u0430\u0431\u0431\u044b\u043d\u0430: "\u041c\u0430\u0493\u0430\u043d \u0431\u0456\u0440 \u0431\u04d9\u043b\u0435 \u043a\u0435\u043b\u0434\u0456. \u0421\u0435\u043d \u043c\u04d9\u0440\u0445\u0430\u043c\u0435\u0442 \u0435\u0442\u0443\u0448\u0456\u043b\u0435\u0440\u0434\u0456\u04a3 \u0430\u0431\u0437\u0430\u043b\u044b\u0441\u044b\u04a3" \u0434\u0435\u043f, \u0436\u0430\u043b\u0431\u0430\u0440\u044b\u043d\u0434\u044b.','\u041c\u04b1\u0441\u0430 (\u0492.\u0421.) \u043e\u043b\u0430\u0440\u0434\u044b\u04a3 \u043c\u0430\u043b\u0434\u0430\u0440\u044b\u043d \u0441\u0443\u0430\u0440\u0434\u044b \u0434\u0430 \u0441\u043e\u0441\u044b\u043d \u043a\u04e9\u043b\u0435\u04a3\u043a\u0435\u0433\u0435 \u0431\u04b1\u0440\u044b\u043b\u044b\u043f: "\u0420\u0430\u0431\u0431\u044b\u043c! \u0421\u0435\u043d \u043c\u0430\u0493\u0430\u043d \u0445\u0430\u0439\u044b\u0440\u0434\u0430\u043d \u043d\u0435 \u0436\u0456\u0431\u0435\u0440\u0441\u0435\u04a3 \u043c\u04b1\u0445\u0442\u0430\u0436\u0431\u044b\u043d" \u0434\u0435\u0434\u0456.','\u049a\u0430\u0448\u0430\u043d \u043e\u043b\u0430\u0440\u0493\u0430 \u0431\u0456\u0440 \u049b\u0430\u0439\u0493\u044b \u0436\u0435\u0442\u0441\u0435: "\u041e\u043b\u0430\u0440 \u0448\u044b\u043d \u043c\u04d9\u043d\u0456\u043d\u0434\u0435 \u0431\u0456\u0437 \u0410\u043b\u043b\u0430\u0493\u0430 \u0442\u04d9\u043d\u0431\u0456\u0437 \u04d9\u0440\u0456 \u041e\u0493\u0430\u043d \u049b\u0430\u0439\u0442\u0443\u0448\u044b\u043c\u044b\u0437" \u0434\u0435\u0434\u0456.',"\u041c\u0456\u043d\u0435 \u0441\u043e\u043b\u0430\u0440\u0493\u0430, \u0420\u0430\u0431\u0431\u044b\u043b\u0430\u0440\u044b \u0436\u0430\u049b\u0442\u0430\u043d \u0436\u0430\u0440\u044b\u043b\u049b\u0430\u0443 \u0436\u04d9\u043d\u0435 \u043c\u04d9\u0440\u049b\u0430\u043c\u0435\u0442 \u0431\u0430\u0440. \u04d8\u0440\u0456 \u043e\u043b\u0430\u0440 \u0442\u0443\u0440\u0430 \u0436\u043e\u043b\u0434\u0430\u0493\u044b\u043b\u0430\u0440.","(\u041c\u04b1\u0445\u0430\u043c\u043c\u0435\u0434 \u0492.\u0421.) \u043a\u04af\u043d\u0434\u0456\u0437\u0434\u0456\u04a3 \u0435\u043a\u0456 \u0436\u0430\u0493\u044b\u043d\u0434\u0430, (\u0442\u0430\u04a3 \u0436\u04d9\u043d\u0435 \u0435\u043a\u0456\u043d\u0434\u0456 \u043d\u0430\u043c\u0430\u0437\u044b) \u0422\u04af\u043d\u043d\u0456\u04a3 \u043a\u04af\u043d\u0434\u0456\u0437\u0433\u0435 \u0442\u0430\u044f\u0443 \u043a\u0435\u0437\u0456\u043d\u0434\u0435, (\u0430\u049b\u0448\u0430\u043c, \u0436\u0430\u0448\u044b\u0439\u044b\u049b) \u043d\u0430\u043c\u0430\u0437\u044b\u043d \u0442\u043e\u043b\u044b\u049b \u043e\u0440\u044b\u043d\u0434\u0430. \u0428\u044b\u043d\u044b\u043d\u0434\u0430 \u0436\u0430\u049b\u0441\u044b\u043b\u044b\u049b\u0442\u0430\u0440, \u0436\u0430\u043c\u0430\u043d\u0434\u044b\u049b\u0442\u0430\u0440\u0434\u044b \u0436\u043e\u044f\u0434\u044b. \u0411\u04b1\u043b \u0442\u04af\u0441\u0456\u043d\u0443\u0448\u0456\u043b\u0435\u0440 \u04af\u0448\u0456\u043d \u0431\u0456\u0440 \u043d\u0430\u0441\u0438\u0445\u0430\u0442.","(\u041c\u04b1\u0445\u0430\u043c\u043c\u0435\u0434 \u0492.\u0421.) \u041a\u0456\u0442\u0430\u043f\u0442\u0430\u043d \u0441\u0430\u0493\u0430\u043d \u0443\u0430\u0445\u0438 \u0435\u0442\u0456\u043b\u0433\u0435\u043d\u0434\u0456 \u0493\u0430\u043d\u0430 \u043e\u049b\u044b \u0434\u0430 \u043d\u0430\u043c\u0430\u0437\u0434\u044b \u043e\u0440\u044b\u043d\u0434\u0430. \u041a\u04af\u0434\u0456\u043a\u0441\u0456\u0437 \u043d\u0430\u043c\u0430\u0437; \u0430\u0440\u0441\u044b\u0437\u0434\u044b\u049b\u0442\u0430\u043d, \u0436\u0430\u043c\u0430\u043d\u0434\u044b\u049b\u0442\u0430\u043d \u0442\u044b\u044f\u0434\u044b. \u04d8\u0440\u0438\u043d\u0435 \u0410\u043b\u043b\u0430\u043d\u044b \u0435\u0441\u043a\u0435 \u0430\u043b\u0443, \u0430\u0441\u0430 \u0456\u0440\u0456 \u043d\u04d9\u0440\u0441\u0435. \u0421\u043e\u043d\u0434\u0430\u0439-\u0430\u049b \u0410\u043b\u043b\u0430 (\u0422.) \u043d\u0435 \u0436\u0430\u0441\u0430\u0493\u0430\u043d\u0434\u0430\u0440\u044b\u04a3\u0434\u044b \u0431\u0456\u043b\u0435\u0434\u0456.","\u041c\u0430\u043b \u043c\u0435\u043d \u0431\u0430\u043b\u0430\u043b\u0430\u0440, \u0434\u04af\u043d\u0438\u0435 \u0442\u0456\u0440\u0448\u0456\u043b\u0456\u0433\u0456\u043d\u0456\u04a3 \u0441\u04d9\u043d\u0456. \u0410\u043b \u0431\u0430\u049b\u0438 \u049b\u0430\u043b\u0430\u0442\u044b\u043d \u0436\u0430\u049b\u0441\u044b\u043b\u044b\u049b\u0442\u0430\u0440 \u0431\u043e\u043b\u0441\u0430, \u0420\u0430\u0431\u0431\u044b\u04a3\u043d\u044b\u04a3 \u049b\u0430\u0441\u044b\u043d\u0434\u0430; \u0442\u0430\u0431\u044b\u0441 \u0431\u043e\u0439\u044b\u043d\u0448\u0430 \u0434\u0430 \u0436\u0430\u049b\u0441\u044b \u04d9\u0440\u0456 \u04af\u043c\u0456\u0442 \u0442\u04b1\u0440\u0493\u044b\u0441\u044b\u043d\u0430\u043d \u0434\u0430 \u0436\u0430\u049b\u0441\u044b.","\u04d8\u0440\u0438\u043d\u0435 \u0441\u0435\u043d \u04af\u0448\u0456\u043d \u0430\u0445\u0438\u0440\u0435\u0442,\u0434\u04af\u043d\u0438\u0435\u0434\u0435\u043d \u0436\u0430\u049b\u0441\u044b.","\u04d8\u043b\u0431\u0435\u0442\u0442\u0435 \u0420\u0430\u0431\u0431\u044b\u04a3 \u0441\u0430\u0493\u0430\u043d \u0431\u0435\u0440\u0435\u0434\u0456 \u0434\u0435 \u0440\u0430\u0437\u044b \u0431\u043e\u043b\u0430\u0441\u044b\u04a3.","\u041d\u0430\u043c\u0430\u0437\u0434\u044b \u0442\u043e\u043b\u044b\u049b \u043e\u0440\u044b\u043d\u0434\u0430\u04a3\u0434\u0430\u0440, \u0437\u0435\u043a\u0435\u0442 \u0431\u0435\u0440\u0456\u04a3\u0434\u0435\u0440. \u04e9\u0437\u0434\u0435\u0440\u0456\u04a3 \u04af\u0448\u0456\u043d \u0456\u043b\u0433\u0435\u0440\u0456 \u0431\u0456\u0440 \u0436\u0430\u049b\u0441\u044b\u043b\u044b\u049b \u0436\u043e\u043b\u0434\u0430\u0441\u0430\u04a3\u0434\u0430\u0440, \u043e\u043d\u044b \u0430\u043b\u043b\u0430\u043d\u044b\u04a3 \u049b\u0430\u0441\u044b\u043d\u0434\u0430 \u0442\u0430\u0431\u0430\u0441\u044b\u04a3\u0434\u0430\u0440. \u0428\u044b\u043d\u044b\u043d\u0434\u0430 \u0410\u043b\u043b\u0430 (\u0422.) \u043d\u0435 \u0456\u0441\u0442\u0435\u0433\u0435\u043d\u0434\u0435\u0440\u0456\u04a3\u0434\u0456 \u0442\u043e\u043b\u044b\u049b \u043a\u04e9\u0440\u0443\u0448\u0456.","(\u041c\u04b1\u0445\u0430\u043c\u043c\u0435\u0434 \u0492.\u0421 \u043e\u043b\u0430\u0440\u0493\u0430) \u0430\u0439\u0442: \u041e\u043b \u0410\u043b\u043b\u0430,\u0431\u0456\u0440\u0435\u0443-\u0430\u049b.","\u041e\u043b \u0441\u043e\u043d\u0434\u0430\u0439 \u0410\u043b\u043b\u0430, \u043a\u04e9\u043a\u0442\u0435\u0440 \u043c\u0435\u043d \u0436\u0435\u0440\u0434\u0456 \u0430\u043b\u0442\u044b \u043a\u04af\u043d\u0434\u0435 \u0436\u0430\u0440\u0430\u0442\u044b\u043f, \u0441\u043e\u0441\u044b\u043d \u0493\u0430\u0440\u0448\u044b\u043d\u044b \u043a\u04e9\u0442\u0435\u0440\u0456\u043b\u0434\u0456. \u041e\u043b, \u0436\u0435\u0440\u0433\u0435 \u043a\u0456\u0440\u0433\u0435\u043d \u043d\u04d9\u0440\u0441\u0435\u043d\u0456 \u04d9\u0440\u0456 \u043e\u0434\u0430\u043d \u0448\u044b\u049b\u049b\u0430\u043d \u043d\u04d9\u0440\u0441\u0435\u043d\u0456 \u0436\u04d9\u043d\u0435 \u043a\u04e9\u043a\u0442\u0435\u043d \u0442\u04af\u0441\u043a\u0435\u043d \u043d\u04d9\u0440\u0441\u0435\u043d\u0456, \u043e\u0493\u0430\u043d \u043a\u04e9\u0442\u0435\u0440\u0456\u043b\u0433\u0435\u043d \u043d\u04d9\u0440\u0441\u0435\u043d\u0456 \u0431\u0456\u043b\u0435\u0434\u0456. \u0421\u043e\u043d\u0434\u0430\u0439-\u0430\u049b \u041e\u043b, \u049b\u0430\u0439\u0434\u0430 \u0431\u043e\u043b\u0441\u0430\u04a3\u0434\u0430\u0440 \u0434\u0430 \u0441\u0435\u043d\u0434\u0435\u0440\u043c\u0435\u043d \u0431\u0456\u0440\u0433\u0435. \u0410\u043b\u043b\u0430 \u043d\u0435 \u0456\u0441\u0442\u0435\u0433\u0435\u043d\u0434\u0435\u0440\u0456\u04a3\u0434\u0456 \u0442\u043e\u043b\u044b\u049b \u043a\u04e9\u0440\u0443\u0448\u0456.","\u041d\u0435\u0433\u0456\u0437\u0456\u043d\u0434\u0435 \u0410\u043b\u043b\u0430 (\u0422.) \u0421\u0435\u043d \u043e\u043b\u0430\u0440\u0434\u044b\u04a3 \u0456\u0448\u0456\u043d\u0434\u0435 \u0431\u043e\u043b\u0493\u0430\u043d\u0434\u0430, \u043e\u043b\u0430\u0440\u0493\u0430 \u0430\u0437\u0430\u043f \u0435\u0442\u043f\u0435\u0441 \u04d9\u0440\u0456 \u043e\u043b\u0430\u0440 \u0436\u0430\u0440\u044b\u043b\u049b\u0430\u0443 \u0442\u0456\u043b\u0435\u0433\u0435\u043d\u0434\u0435 \u0434\u0435 \u0410\u043b\u043b\u0430, \u043e\u043b\u0430\u0440\u0434\u044b \u0430\u0437\u0430\u043f \u049b\u044b\u043b\u043c\u0430\u0439\u0434\u044b.","\u0415\u0433\u0435\u0440 \u0448\u04af\u043a\u0456\u0440\u043b\u0456\u043a \u0435\u0442\u0456\u043f, \u0438\u043c\u0430\u043d \u043a\u0435\u043b\u0442\u0456\u0440\u0441\u0435\u04a3\u0434\u0435\u0440, \u0410\u043b\u043b\u0430 \u0441\u0435\u043d\u0434\u0435\u0440\u0434\u0456 \u043d\u0435\u0433\u0435 \u0430\u0437\u0430\u043f \u049b\u044b\u043b\u0441\u044b\u043d? \u04e8\u0439\u0442\u043a\u0435\u043d\u0456, \u0410\u043b\u043b\u0430 (\u0422.) \u0448\u04af\u043a\u0456\u0440\u043b\u0456\u043a\u0442\u0456 \u0431\u0430\u0493\u0430\u043b\u0430\u0443\u0448\u044b, \u0442\u043e\u043b\u044b\u049b \u0431\u0456\u043b\u0443\u0448\u0456."],t.li)
